mapper.select:
select wpc.id, wpc.code, wpc.sort_order, wpc.is_show, wpci.locale, wpci.name, wpci.description, wpci.image_attachment_id from website_product_category wpc join website_product_category_i18n wpci on wpci.website_product_category_id = wpc.id where wpci.locale = #{query.locale} and wpc.is_deleted = false and wpci.is_deleted = false
and wpc.id = #{query.id}
and wpci.website_product_category_id = #{query.websiteProductCategoryId}
and wpc.code like concat('%', #{query.code}, '%')
and wpci.name like concat('%', #{query.name}, '%')
and wpci.description like concat('%', #{query.description}, '%')
and wpci.image_attachment_id = #{query.imageAttachmentId}
and wpc.sort_order = #{query.sortOrder}
and wpc.is_show = #{query.isShow}
order by wpc.sort_order asc, wpc.id asc
